import AccessorArray = require( '@stdlib/array/base/accessor' );
import gfillDiagonal = require( './index' );


// TESTS //

// The function returns a collection...
{
	const A = new Float64Array( 6 );

	gfillDiagonal( 'row-major', 2, 3, 0, 5.0, A, 3 ); // $ExpectType Collection<number>
	gfillDiagonal( 'column-major', 2, 3, 0, 5.0, new AccessorArray( A ), 2 ); // $ExpectType AccessorArrayLike<number>
}

// The compiler throws an error if the function is provided a first argument which is not a string...
{
	const A = new Float64Array( 6 );

	gfillDiagonal( 10, 2, 3, 0, 5.0, A, 3 ); // $ExpectError
	gfillDiagonal( true, 2, 3, 0, 5.0, A, 3 ); // $ExpectError
	gfillDiagonal( null, 2, 3, 0, 5.0, A, 3 ); // $ExpectError
	gfillDiagonal( undefined, 2, 3, 0, 5.0, A, 3 ); // $ExpectError
	gfillDiagonal( [], 2, 3, 0, 5.0, A, 3 ); // $ExpectError
	gfillDiagonal( {}, 2, 3, 0, 5.0, A, 3 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a number...
{
	const A = new Float64Array( 6 );

	gfillDiagonal( 'row-major', '2', 3, 0, 5.0, A, 3 ); // $ExpectError
	gfillDiagonal( 'row-major', true, 3, 0, 5.0, A, 3 ); // $ExpectError
	gfillDiagonal( 'row-major', null, 3, 0, 5.0, A, 3 ); // $ExpectError
	gfillDiagonal( 'row-major', undefined, 3, 0, 5.0, A, 3 ); // $ExpectError
	gfillDiagonal( 'row-major', [], 3, 0, 5.0, A, 3 ); // $ExpectError
	gfillDiagonal( 'row-major', {}, 3, 0, 5.0, A, 3 ); // $ExpectError
}

// The compiler throws an error if the function is provided a third argument which is not a number...
{
	const A = new Float64Array( 6 );

	gfillDiagonal( 'row-major', 2, '3', 0, 5.0, A, 3 ); // $ExpectError
	gfillDiagonal( 'row-major', 2, true, 0, 5.0, A, 3 ); // $ExpectError
	gfillDiagonal( 'row-major', 2, null, 0, 5.0, A, 3 ); // $ExpectError
	gfillDiagonal( 'row-major', 2, undefined, 0, 5.0, A, 3 ); // $ExpectError
	gfillDiagonal( 'row-major', 2, [], 0, 5.0, A, 3 ); // $ExpectError
	gfillDiagonal( 'row-major', 2, {}, 0, 5.0, A, 3 ); // $ExpectError
}

// The compiler throws an error if the function is provided a fourth argument which is not a number...
{
	const A = new Float64Array( 6 );

	gfillDiagonal( 'row-major', 2, 3, '0', 5.0, A, 3 ); // $ExpectError
	gfillDiagonal( 'row-major', 2, 3, true, 5.0, A, 3 ); // $ExpectError
	gfillDiagonal( 'row-major', 2, 3, null, 5.0, A, 3 ); // $ExpectError
	gfillDiagonal( 'row-major', 2, 3, undefined, 5.0, A, 3 ); // $ExpectError
	gfillDiagonal( 'row-major', 2, 3, [], 5.0, A, 3 ); // $ExpectError
	gfillDiagonal( 'row-major', 2, 3, {}, 5.0, A, 3 ); // $ExpectError
}

// The compiler throws an error if the function is provided a sixth argument which is not a collection...
{
	gfillDiagonal( 'row-major', 2, 3, 0, 5.0, 10, 3 ); // $ExpectError
	gfillDiagonal( 'row-major', 2, 3, 0, 5.0, true, 3 ); // $ExpectError
	gfillDiagonal( 'row-major', 2, 3, 0, 5.0, null, 3 ); // $ExpectError
	gfillDiagonal( 'row-major', 2, 3, 0, 5.0, undefined, 3 ); // $ExpectError
	gfillDiagonal( 'row-major', 2, 3, 0, 5.0, {}, 3 ); // $ExpectError
}

// The compiler throws an error if the function is provided a seventh argument which is not a number...
{
	const A = new Float64Array( 6 );

	gfillDiagonal( 'row-major', 2, 3, 0, 5.0, A, '3' ); // $ExpectError
	gfillDiagonal( 'row-major', 2, 3, 0, 5.0, A, true ); // $ExpectError
	gfillDiagonal( 'row-major', 2, 3, 0, 5.0, A, null ); // $ExpectError
	gfillDiagonal( 'row-major', 2, 3, 0, 5.0, A, undefined ); // $ExpectError
	gfillDiagonal( 'row-major', 2, 3, 0, 5.0, A, [] ); // $ExpectError
	gfillDiagonal( 'row-major', 2, 3, 0, 5.0, A, {} ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const A = new Float64Array( 6 );

	gfillDiagonal(); // $ExpectError
	gfillDiagonal( 'row-major' ); // $ExpectError
	gfillDiagonal( 'row-major', 2 ); // $ExpectError
	gfillDiagonal( 'row-major', 2, 3 ); // $ExpectError
	gfillDiagonal( 'row-major', 2, 3, 0 ); // $ExpectError
	gfillDiagonal( 'row-major', 2, 3, 0, 5.0 ); // $ExpectError
	gfillDiagonal( 'row-major', 2, 3, 0, 5.0, A ); // $ExpectError
	gfillDiagonal( 'row-major', 2, 3, 0, 5.0, A, 3, 10 ); // $ExpectError
}

// Attached to main export is an `ndarray` method which returns a collection...
{
	const A = new Float64Array( 6 );

	gfillDiagonal.ndarray( 2, 3, 0, 5.0, A, 3, 1, 0 ); // $ExpectType Collection<number>
	gfillDiagonal.ndarray( 2, 3, 0, 5.0, new AccessorArray( A ), 3, 1, 0 ); // $ExpectType AccessorArrayLike<number>
}

// The compiler throws an error if the `ndarray` method is provided a first argument which is not a number...
{
	const A = new Float64Array( 6 );

	gfillDiagonal.ndarray( '2', 3, 0, 5.0, A, 3, 1, 0 ); // $ExpectError
	gfillDiagonal.ndarray( true, 3, 0, 5.0, A, 3, 1, 0 ); // $ExpectError
	gfillDiagonal.ndarray( null, 3, 0, 5.0, A, 3, 1, 0 ); // $ExpectError
	gfillDiagonal.ndarray( undefined, 3, 0, 5.0, A, 3, 1, 0 ); // $ExpectError
	gfillDiagonal.ndarray( [], 3, 0, 5.0, A, 3, 1, 0 ); // $ExpectError
	gfillDiagonal.ndarray( {}, 3, 0, 5.0, A, 3, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a second argument which is not a number...
{
	const A = new Float64Array( 6 );

	gfillDiagonal.ndarray( 2, '3', 0, 5.0, A, 3, 1, 0 ); // $ExpectError
	gfillDiagonal.ndarray( 2, true, 0, 5.0, A, 3, 1, 0 ); // $ExpectError
	gfillDiagonal.ndarray( 2, null, 0, 5.0, A, 3, 1, 0 ); // $ExpectError
	gfillDiagonal.ndarray( 2, undefined, 0, 5.0, A, 3, 1, 0 ); // $ExpectError
	gfillDiagonal.ndarray( 2, [], 0, 5.0, A, 3, 1, 0 ); // $ExpectError
	gfillDiagonal.ndarray( 2, {}, 0, 5.0, A, 3, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a third argument which is not a number...
{
	const A = new Float64Array( 6 );

	gfillDiagonal.ndarray( 2, 3, '0', 5.0, A, 3, 1, 0 ); // $ExpectError
	gfillDiagonal.ndarray( 2, 3, true, 5.0, A, 3, 1, 0 ); // $ExpectError
	gfillDiagonal.ndarray( 2, 3, null, 5.0, A, 3, 1, 0 ); // $ExpectError
	gfillDiagonal.ndarray( 2, 3, undefined, 5.0, A, 3, 1, 0 ); // $ExpectError
	gfillDiagonal.ndarray( 2, 3, [], 5.0, A, 3, 1, 0 ); // $ExpectError
	gfillDiagonal.ndarray( 2, 3, {}, 5.0, A, 3, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a fifth argument which is not a collection...
{
	gfillDiagonal.ndarray( 2, 3, 0, 5.0, 10, 3, 1, 0 ); // $ExpectError
	gfillDiagonal.ndarray( 2, 3, 0, 5.0, true, 3, 1, 0 ); // $ExpectError
	gfillDiagonal.ndarray( 2, 3, 0, 5.0, null, 3, 1, 0 ); // $ExpectError
	gfillDiagonal.ndarray( 2, 3, 0, 5.0, undefined, 3, 1, 0 ); // $ExpectError
	gfillDiagonal.ndarray( 2, 3, 0, 5.0, {}, 3, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a sixth argument which is not a number...
{
	const A = new Float64Array( 6 );

	gfillDiagonal.ndarray( 2, 3, 0, 5.0, A, '3', 1, 0 ); // $ExpectError
	gfillDiagonal.ndarray( 2, 3, 0, 5.0, A, true, 1, 0 ); // $ExpectError
	gfillDiagonal.ndarray( 2, 3, 0, 5.0, A, null, 1, 0 ); // $ExpectError
	gfillDiagonal.ndarray( 2, 3, 0, 5.0, A, undefined, 1, 0 ); // $ExpectError
	gfillDiagonal.ndarray( 2, 3, 0, 5.0, A, [], 1, 0 ); // $ExpectError
	gfillDiagonal.ndarray( 2, 3, 0, 5.0, A, {}, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a seventh argument which is not a number...
{
	const A = new Float64Array( 6 );

	gfillDiagonal.ndarray( 2, 3, 0, 5.0, A, 3, '1', 0 ); // $ExpectError
	gfillDiagonal.ndarray( 2, 3, 0, 5.0, A, 3, true, 0 ); // $ExpectError
	gfillDiagonal.ndarray( 2, 3, 0, 5.0, A, 3, null, 0 ); // $ExpectError
	gfillDiagonal.ndarray( 2, 3, 0, 5.0, A, 3, undefined, 0 ); // $ExpectError
	gfillDiagonal.ndarray( 2, 3, 0, 5.0, A, 3, [], 0 ); // $ExpectError
	gfillDiagonal.ndarray( 2, 3, 0, 5.0, A, 3, {}, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided an eighth argument which is not a number...
{
	const A = new Float64Array( 6 );

	gfillDiagonal.ndarray( 2, 3, 0, 5.0, A, 3, 1, '0' ); // $ExpectError
	gfillDiagonal.ndarray( 2, 3, 0, 5.0, A, 3, 1, true ); // $ExpectError
	gfillDiagonal.ndarray( 2, 3, 0, 5.0, A, 3, 1, null ); // $ExpectError
	gfillDiagonal.ndarray( 2, 3, 0, 5.0, A, 3, 1, undefined ); // $ExpectError
	gfillDiagonal.ndarray( 2, 3, 0, 5.0, A, 3, 1, [] ); // $ExpectError
	gfillDiagonal.ndarray( 2, 3, 0, 5.0, A, 3, 1, {} ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided an unsupported number of arguments...
{
	const A = new Float64Array( 6 );

	gfillDiagonal.ndarray(); // $ExpectError
	gfillDiagonal.ndarray( 2 ); // $ExpectError
	gfillDiagonal.ndarray( 2, 3 ); // $ExpectError
	gfillDiagonal.ndarray( 2, 3, 0 ); // $ExpectError
	gfillDiagonal.ndarray( 2, 3, 0, 5.0 ); // $ExpectError
	gfillDiagonal.ndarray( 2, 3, 0, 5.0, A ); // $ExpectError
	gfillDiagonal.ndarray( 2, 3, 0, 5.0, A, 3 ); // $ExpectError
	gfillDiagonal.ndarray( 2, 3, 0, 5.0, A, 3, 1 ); // $ExpectError
	gfillDiagonal.ndarray( 2, 3, 0, 5.0, A, 3, 1, 0, 10 ); // $ExpectError
}
